INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20A9LKV', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A parking garage charges a flat fee of $\\$4$ plus $\\$1.50$ per hour. A driver has at most $\\$19$ to spend on parking. Which inequality represents the number of hours $h$ the driver can park?', NULL, $lyceon_json$[{"key":"A","text":"$4 + 1.5h \\leq 19$"},{"key":"B","text":"$4 + 1.5h \\geq 19$"},{"key":"C","text":"$1.5h \\leq 19$"},{"key":"D","text":"$4h + 1.5 \\leq 19$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of $\\$4$ plus $\\$1.50$ per hour, giving $4 + 1.5h$. Since the driver has at most $\\$19$, this total must be less than or equal to $19$, yielding $4 + 1.5h \\leq 19$. Using $\\geq$ reverses the constraint, as though the driver must spend at least $\\$19$. Omitting the flat fee of $\\$4$ and writing $1.5h \\leq 19$ ignores part of the cost structure. Writing $4h + 1.5$ swaps the coefficient and constant, misassigning the per-hour rate and flat fee.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20EISV3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $2x^2 - 14x = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 0$ and $x = 7$"},{"key":"B","text":"$x = 0$ and $x = -7$"},{"key":"C","text":"$x = 2$ and $x = 7$"},{"key":"D","text":"$x = 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor out $2x$: $2x(x - 7) = 0$. Setting each factor equal to zero gives $x = 0$ or $x = 7$. The distractor $x = 0$ and $x = -7$ results from a sign error when solving $x - 7 = 0$. The distractor $x = 2$ and $x = 7$ comes from incorrectly splitting $2x^2 - 14x = 0$ as $(x - 2)(x - 7) = 0$ instead of factoring out $2x$. The distractor $x = 7$ only accounts for the non-zero solution, omitting $x = 0$ from the factored form $2x(x - 7) = 0$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
