INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22G7WWP', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(2, 13)$ and $(5, 31)$. What is the $x$-intercept of this line? Express your answer as a fraction if necessary.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1/6', ARRAY['-1/6', '-0.166', '-.166', '-0.167', '-.167'], E'The slope is $m = \\frac{31 - 13}{5 - 2} = \\frac{18}{3} = 6$. Using point-slope form with $(2, 13)$: $y - 13 = 6(x - 2)$, which simplifies to $y = 6x + 1$. Setting $y = 0$: $0 = 6x + 1$, so $x = -\\frac{1}{6}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22KRDI2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 14x + 6y - 23 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Rewrite by completing the square. Group $x$ and $y$ terms: $(x^2 - 14x) + (y^2 + 6y) = 23$. Complete the square for $x$: $(x^2 - 14x + 49) = (x-7)^2$, adding $49$. Complete the square for $y$: $(y^2 + 6y + 9) = (y+3)^2$, adding $9$. So $(x-7)^2 + (y+3)^2 = 23 + 49 + 9 = 81$. The radius is $\\sqrt{81} = 9$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
