INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2435I5E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$ units. What is the area of the circle, in square units?', NULL, $lyceon_json$[{"key":"A","text":"$289\\pi$"},{"key":"B","text":"$1156\\pi$"},{"key":"C","text":"$17\\pi$"},{"key":"D","text":"$34\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is $\\frac{34}{2} = 17$. The area is $\\pi r^2 = \\pi(17)^2 = 289\\pi$ square units. The distractor $1156\\pi$ uses the diameter instead of the radius, computing $\\pi(34)^2 = 1156\\pi$. The distractor $17\\pi$ gives the radius times $\\pi$, which is not a correct formula for area (it confuses area with a partial circumference computation). The distractor $34\\pi$ computes the circumference ($\\pi d = 34\\pi$) instead of the area.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24KQK1J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer produces $7$ pages every $2$ minutes. At this rate, how many minutes will it take to print $91$ pages?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$22$"},{"key":"C","text":"$26$"},{"key":"D","text":"$45.5$"}]$lyceon_json$::jsonb, 'C', NULL, E'The printer produces $7$ pages in $2$ minutes, so its rate is $\\frac{7}{2}$ pages per minute. To find the time for $91$ pages: $\\frac{91}{7/2} = 91 \\times \\frac{2}{7} = 26$ minutes. The distractor $13$ results from dividing $91 \\div 7 = 13$ but forgetting to account for the $2$-minute interval. The distractor $22$ comes from an arithmetic miscalculation. The distractor $45.5$ results from dividing $91 \\div 2$, using the wrong quantity from the rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25BLAI3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up the wholesale price of an item by $40\\%$ and then offers customers a $25\\%$ discount off the marked-up price. If a customer pays $\\$73.50$ for the item, what was the wholesale price?', NULL, $lyceon_json$[{"key":"A","text":"$\\$52.50$"},{"key":"B","text":"$\\$58.80$"},{"key":"C","text":"$\\$70.00$"},{"key":"D","text":"$\\$98.00$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $w$ be the wholesale price. After a $40\\%$ markup, the price is $1.40w$. After a $25\\%$ discount, the customer pays $0.75 \\times 1.40w = 1.05w$. Setting $1.05w = 73.50$ gives $w = \\frac{73.50}{1.05} = \\$70.00$. The distractor $\\$52.50$ results from dividing by $1.40$ alone ($73.50 \\div 1.40$), ignoring the discount. The distractor $\\$58.80$ results from dividing by $1.25$ ($73.50 \\div 1.25$), treating the discount percentage as a markup reversal. The distractor $\\$98.00$ results from dividing by $0.75$ alone ($73.50 \\div 0.75$), ignoring the markup.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25R26DA', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bookstore sells hardcovers for $\\$23$ each and paperbacks for $\\$9$ each. On a particular day, the store sold a combined total of $41$ books and collected $\\$565$ in revenue from these sales. How many hardcovers were sold?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$14$"},{"key":"C","text":"$27$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ be the number of hardcovers and $p$ be the number of paperbacks. Then $h + p = 41$ and $23h + 9p = 565$. From the first equation, $p = 41 - h$. Substituting: $23h + 9(41 - h) = 565$, so $23h + 369 - 9h = 565$, giving $14h = 196$ and $h = 14$ (with $p = 27$). Verification: $23(14) + 9(27) = 322 + 243 = 565$. The value $12$ arises from an arithmetic slip in simplifying. The value $27$ is the number of paperbacks, not hardcovers. The value $29$ results from setting up the revenue equation incorrectly, such as swapping the prices of hardcovers and paperbacks.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2673R3L', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $y = x^2 - 3x + 1$ and $y = 5x - 11$, what is the sum of the $x$-coordinates of the solutions to this system of equations?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Set the expressions equal: $x^2 - 3x + 1 = 5x - 11$. Rearranging gives $x^2 - 8x + 12 = 0$. Factoring: $(x - 2)(x - 6) = 0$, so $x = 2$ or $x = 6$. The sum of the $x$-coordinates is $2 + 6 = 8$. This can also be found directly using Vieta''s formulas: for $x^2 - 8x + 12 = 0$, the sum of the roots equals $-(-8)/1 = 8$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26BGI4C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the relationship between hours of sunlight per day ($x$) and the height of a plant in centimeters ($y$). The line of best fit is $y = 2.7x + 3.1$. Which of the following is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight per day, the predicted plant height increases by $2.7$ centimeters."},{"key":"B","text":"For each additional centimeter of plant height, the predicted number of hours of sunlight per day increases by $2.7$."},{"key":"C","text":"A plant that receives no sunlight is predicted to be $2.7$ centimeters tall."},{"key":"D","text":"The plant grows a total of $2.7$ centimeters during the entire study period."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $2.7$ represents the predicted change in $y$ (plant height in centimeters) for each one-unit increase in $x$ (hours of sunlight per day). The interpretation that each additional centimeter of height corresponds to $2.7$ more hours of sunlight reverses the roles of the independent and dependent variables. The interpretation that a plant with no sunlight is $2.7$ centimeters tall confuses the slope ($2.7$) with the $y$-intercept ($3.1$). The interpretation that total growth is $2.7$ centimeters confuses the per-unit rate of change with cumulative change over the study.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26L8QW5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher randomly assigned 78 volunteers recruited from a local gym to two groups. One group performed a specific stretching routine before every workout, and the other group did not stretch. After 6 weeks, the stretching group reported $31\\%$ fewer muscle strains than the non-stretching group. Which of the following conclusions is best supported by this study?', NULL, $lyceon_json$[{"key":"A","text":"The stretching routine causes a reduction in muscle strains among all adults who exercise at gyms."},{"key":"B","text":"The stretching routine causes a reduction in muscle strains among the volunteers in the study."},{"key":"C","text":"The stretching routine is associated with fewer muscle strains, but a causal relationship cannot be established."},{"key":"D","text":"All adults who exercise at gyms should perform the stretching routine to prevent injuries."}]$lyceon_json$::jsonb, 'B', NULL, E'Random assignment to treatment and control groups allows a causal conclusion, so causation can be established for the participants in this study. However, the volunteers were recruited from a single gym and were not randomly selected from a broader population, so the results cannot be generalized beyond the study participants. The conclusion that the routine causes a reduction among all gym-going adults overgeneralizes from a non-representative sample. The conclusion that only an association exists ignores the random assignment, which does support causation. The recommendation that all adults should stretch overgeneralizes and makes a prescriptive claim not warranted by the study design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27M3623', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 625 households in a county found a mean monthly electricity bill of $\\$137$ with a margin of error of $\\$11$ at $95\\%$ confidence. A second independent random sample of 2,500 households from the same county found a mean monthly electricity bill of $\\$141$ with a margin of error of $\\$5.50$ at $95\\%$ confidence. Based on both results, which of the following is a plausible value for the true mean monthly electricity bill for all households in the county?', NULL, $lyceon_json$[{"key":"A","text":"$\\$128$"},{"key":"B","text":"$\\$133$"},{"key":"C","text":"$\\$139$"},{"key":"D","text":"$\\$148$"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sample yields a $95\\%$ confidence interval of $(\\$126, \\$148)$ and the second yields $(\\$135.50, \\$146.50)$. A plausible value for the true mean must fall within both intervals, so it must be between $\\$135.50$ and $\\$146.50$. Only $\\$139$ falls in this overlap region. The distractor $\\$128$ lies within the first interval but below the lower bound of the second. The distractor $\\$133$ is also within the first interval but outside the second. The distractor $\\$148$ is at the upper edge of the first interval but above the upper bound of the second.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28OF1HP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reports that adults who drink at least 3 cups of green tea per day have lower average blood pressure than adults who do not drink green tea. The data were collected by surveying 1,200 adults about their tea-drinking habits and measuring their blood pressure. Which of the following conclusions is best supported by this study?', NULL, $lyceon_json$[{"key":"A","text":"Drinking green tea causes lower blood pressure in adults."},{"key":"B","text":"There is an association between drinking green tea and lower blood pressure among the surveyed adults."},{"key":"C","text":"Drinking green tea is more effective than medication at lowering blood pressure."},{"key":"D","text":"Adults who do not drink green tea should start drinking it to lower their blood pressure."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participants were surveyed about existing habits rather than randomly assigned to drink or not drink green tea, this is an observational study. Observational studies can establish associations but cannot establish causation, since confounding variables (such as overall diet or exercise) may explain the difference. The claim that green tea causes lower blood pressure incorrectly draws a causal conclusion from an observational design. The claim about medication has no basis in the study, which did not compare tea to any medication. The recommendation to start drinking green tea to lower blood pressure is a causal prescription that the observational design cannot support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29EN7JD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 1.3x + 4.7$. Using this model, what is the predicted value of $y$ when $x = 11$?', NULL, $lyceon_json$[{"key":"A","text":"$14.3$"},{"key":"B","text":"$19.0$"},{"key":"C","text":"$19.4$"},{"key":"D","text":"$66.0$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 11$ into the equation: $y = 1.3(11) + 4.7 = 14.3 + 4.7 = 19.0$. The distractor $14.3$ results from computing $1.3 \\times 11$ but omitting the constant term $4.7$. The distractor $19.4$ results from an arithmetic error in computing $1.3 \\times 11$ as $14.7$ instead of $14.3$. The distractor $66.0$ results from computing $(1.3 + 4.7) \\times 11 = 6 \\times 11$, incorrectly adding the slope and intercept before multiplying.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29V84ZR', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $g$ is defined by $g(x) = ax + b$, where $a$ and $b$ are constants. If $g(3) = 29$ and $g(11) = 69$, what is the value of $g(-2)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Using the two given values to find the slope: $a = \\frac{69 - 29}{11 - 3} = \\frac{40}{8} = 5$. Substituting into $g(3) = 29$: $5(3) + b = 29$, so $15 + b = 29$ and $b = 14$. Therefore $g(x) = 5x + 14$, and $g(-2) = 5(-2) + 14 = -10 + 14 = 4$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AUJ3G7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A class has 31 students. Of these, 13 are members of the debate club and the rest are not. If one student is selected at random from the class, what is the probability that the student is NOT a member of the debate club?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{31}$"},{"key":"B","text":"$\\frac{18}{31}$"},{"key":"C","text":"$\\frac{18}{13}$"},{"key":"D","text":"$\\frac{13}{18}$"}]$lyceon_json$::jsonb, 'B', NULL, E'There are $31 - 13 = 18$ students who are not in the debate club, so the probability is $\\frac{18}{31}$. The distractor $\\frac{13}{31}$ gives the probability of being in the debate club rather than not being in it, reversing what the question asks. The distractor $\\frac{18}{13}$ incorrectly uses the number of debate club members as the denominator instead of the total number of students. The distractor $\\frac{13}{18}$ similarly uses an incorrect denominator by dividing debate members by non-members rather than by the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AXKCGL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $5$ centimeters and a height of $18$ centimeters. A cone has the same radius and the same height as the cylinder. What is the volume of the cone, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$150\\pi$"},{"key":"B","text":"$450\\pi$"},{"key":"C","text":"$90\\pi$"},{"key":"D","text":"$300\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(5)^2(18) = \\frac{1}{3}\\pi(25)(18) = \\frac{450\\pi}{3} = 150\\pi$ cubic centimeters. The distractor $450\\pi$ computes the volume of the cylinder ($\\pi r^2 h = 450\\pi$) instead of the cone, omitting the $\\frac{1}{3}$ factor. The distractor $90\\pi$ results from an arithmetic slip such as computing $25 \\times 18 = 270$ instead of $450$, then dividing by $3$. The distractor $300\\pi$ uses $\\frac{2}{3}$ instead of $\\frac{1}{3}$, perhaps confusing the cone formula with the hemisphere formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B9K5V0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A university administrator wants to estimate the proportion of all 8,200 undergraduates who use the campus tutoring center. She emails a survey to 500 randomly selected undergraduates and receives 174 responses. Of those who responded, 63 reported using the tutoring center. The administrator calculates a $95\\%$ confidence interval based on the 174 responses. Which of the following best explains why the resulting confidence interval may not be valid for estimating the proportion among all 8,200 undergraduates?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 174 responses is too small to construct a valid confidence interval."},{"key":"B","text":"The 326 students who did not respond may differ systematically from those who did, introducing nonresponse bias."},{"key":"C","text":"The administrator should have surveyed all 8,200 undergraduates instead of using a sample."},{"key":"D","text":"The margin of error will be too large because the sample was drawn from only one university."}]$lyceon_json$::jsonb, 'B', NULL, E'The critical flaw is nonresponse bias: only 174 out of 500 selected students responded ($34.8\\%$ response rate), and those who chose to respond may have different tutoring-center usage patterns than those who did not. This makes the 174 respondents a non-representative subset, invalidating the confidence interval for the full population. The distractor claiming 174 is too small is incorrect because 174 responses easily satisfy the conditions for constructing a confidence interval ($np$ and $n(1-p)$ both exceed 10). The distractor suggesting all 8,200 should be surveyed misunderstands the purpose of sampling — a properly drawn random sample is sufficient. The distractor about the margin of error being too large because of a single university confuses population scope; the administrator''s goal is to estimate the proportion at this university, so drawing from it is correct.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C3004V', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $5x - 8 > 27$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding $8$ to both sides gives $5x > 35$, so $x > 7$. Only $9$ is strictly greater than $7$. The value $7$ results from including the boundary point, but the inequality is strict ($>$, not $\\geq$), so $7$ does not satisfy it. The value $5$ comes from an arithmetic slip such as miscalculating $27 + 8$ or $35 \\div 5$. The value $3$ reflects a fundamental gap in solving the inequality, yielding a value well below the boundary.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DFFMP8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(2x^2 - 7x + 4) - (x^2 + 5x - 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$5x^2 - 26x + 21$"},{"key":"B","text":"$5x^2 - 16x + 3$"},{"key":"C","text":"$5x^2 - 26x + 3$"},{"key":"D","text":"$7x^2 - 26x + 21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the $3$ gives $6x^2 - 21x + 12$. Distributing the negative sign gives $-x^2 - 5x + 9$. Combining: $6x^2 - x^2 = 5x^2$, $-21x - 5x = -26x$, and $12 + 9 = 21$, yielding $5x^2 - 26x + 21$. The distractor $5x^2 - 16x + 3$ results from failing to distribute the negative sign to $+5x$ (keeping it as $-5x$ and computing $-21x + 5x = -16x$) and subtracting $12 - 9 = 3$. The distractor $5x^2 - 26x + 3$ gets the $x$-terms correct but incorrectly subtracts the constants ($12 - 9 = 3$) instead of adding ($12 + 9 = 21$). The distractor $7x^2 - 26x + 21$ adds $6x^2 + x^2 = 7x^2$ instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DZPXAS', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $11x - 33 = 88$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$8$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding $33$ to both sides gives $11x = 121$, and dividing both sides by $11$ gives $x = 11$. The value $5$ results from an arithmetic slip, such as computing $88 + 33 = 121$ correctly but dividing by $11$ incorrectly. The value $8$ arises from dividing $88$ by $11$ without first adding $33$, an equation setup error. The value $-11$ comes from a sign error when dividing $121$ by $11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GC47MP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $11, 14, 14, 17, 19, 23, 28$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$17$"},{"key":"C","text":"$18$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set has $7$ values listed in order. The median is the middle (4th) value, which is $17$. The distractor $14$ is the mode (most frequent value), not the median. The distractor $18$ is the mean ($\\frac{126}{7} = 18$), which is a different measure of center. The distractor $19$ results from selecting the wrong positional value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GHCJG5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tested a new sleep supplement. Researchers recruited 120 participants from a pool of patients at a sleep clinic who reported difficulty sleeping. Participants chose whether to take the supplement or a placebo for 8 weeks. At the end of the study, the supplement group reported sleeping an average of 47 minutes more per night than the placebo group. The company claims the supplement is effective at improving sleep for all adults. Which of the following is the strongest reason this claim may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The study relied on self-reported sleep duration, which may not be accurate."},{"key":"B","text":"The 8-week duration is too short to determine long-term effectiveness."},{"key":"C","text":"Participants chose their own group rather than being randomly assigned, so differences in outcomes could be due to preexisting differences between the groups rather than the supplement."},{"key":"D","text":"The sample size of 120 is too small to detect a meaningful difference in sleep duration."}]$lyceon_json$::jsonb, 'C', NULL, E'The most fundamental flaw is the lack of random assignment. Because participants self-selected into the supplement or placebo group, the groups may differ in ways that affect the outcome — for example, participants who chose the supplement may have been more motivated to improve their sleep or may have had different baseline sleep patterns. Without random assignment, these confounding variables cannot be ruled out, so a causal claim about the supplement''s effectiveness is not supported. Self-reported data is a valid concern but is a measurement-quality issue, not a design flaw that undermines the causal claim itself. The 8-week duration is a scope limitation but does not explain why the observed difference may not be caused by the supplement. A sample of 120 is generally adequate for detecting a 47-minute difference, so sample size is not the primary issue.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H1KXNB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 + 2x + k$ and $y = 7x - 3$ has exactly one solution. What is the $y$-coordinate of that solution?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{29}{2}$"},{"key":"B","text":"$\\frac{35}{2}$"},{"key":"C","text":"$\\frac{5}{2}$"},{"key":"D","text":"$\\frac{13}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $x^2 + 2x + k = 7x - 3$, which gives $x^2 - 5x + (k + 3) = 0$. For exactly one solution, the discriminant equals zero: $25 - 4(k + 3) = 0$, so $25 - 4k - 12 = 0$, giving $k = \\frac{13}{4}$. With this $k$, the equation $x^2 - 5x + \\frac{25}{4} = 0$ has the solution $x = \\frac{5}{2}$. Substituting into $y = 7x - 3$: $y = 7 \\cdot \\frac{5}{2} - 3 = \\frac{35}{2} - 3 = \\frac{29}{2}$. The distractor $\\frac{35}{2}$ comes from computing $7 \\cdot \\frac{5}{2}$ but forgetting to subtract $3$. The distractor $\\frac{5}{2}$ is the $x$-coordinate, not the $y$-coordinate. The distractor $\\frac{13}{4}$ is the value of $k$, not the $y$-coordinate of the solution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H49L3Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle has center $(2, -1)$ and passes through the point $(11, 11)$. What is the slope of the line tangent to the circle at the point $(11, 11)$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{3}{4}$"},{"key":"B","text":"$\\frac{4}{3}$"},{"key":"C","text":"$\\frac{3}{4}$"},{"key":"D","text":"$-\\frac{4}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of the radius from center $(2, -1)$ to the point $(11, 11)$ is $\\frac{11 - (-1)}{11 - 2} = \\frac{12}{9} = \\frac{4}{3}$. A tangent line is perpendicular to the radius at the point of tangency, so its slope is the negative reciprocal of $\\frac{4}{3}$, which is $-\\frac{3}{4}$. The distractor $\\frac{4}{3}$ is the slope of the radius itself, not the tangent, reflecting a failure to apply the perpendicularity condition. The distractor $\\frac{3}{4}$ takes the reciprocal of the radius slope but omits the negation. The distractor $-\\frac{4}{3}$ negates the radius slope without taking the reciprocal.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HVJOBH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'Two machines, $P$ and $Q$, fill bottles at constant rates. Machine $P$ fills $23$ bottles in $5$ minutes, and Machine $Q$ fills $19$ bottles in $4$ minutes. If both machines work together for $20$ minutes, how many bottles do they fill in total?', NULL, $lyceon_json$[{"key":"A","text":"$92$"},{"key":"B","text":"$95$"},{"key":"C","text":"$187$"},{"key":"D","text":"$210$"}]$lyceon_json$::jsonb, 'C', NULL, E'Machine $P$ fills $\\frac{23}{5}$ bottles per minute, so in $20$ minutes it fills $23 \\times \\frac{20}{5} = 92$ bottles. Machine $Q$ fills $\\frac{19}{4}$ bottles per minute, so in $20$ minutes it fills $19 \\times \\frac{20}{4} = 95$ bottles. Together they fill $92 + 95 = 187$ bottles. The distractor $92$ counts only Machine $P$''s output. The distractor $95$ counts only Machine $Q$''s output. The distractor $210$ results from adding $23 + 19 = 42$ and dividing by $4$ minutes only: $\\frac{42}{4} \\times 20 = 210$, incorrectly using the shorter time interval as the combined rate denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HXS9QP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A right triangular prism has a triangular base with legs of length $8$ and $15$. The height of the prism is $11$. What is the volume of the prism?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '660', ARRAY['660'], E'The base is a right triangle with legs $8$ and $15$. The area of the base is $\\frac{1}{2}(8)(15) = 60$ square units. The volume of the prism is base area times height: $60 \\times 11 = 660$ cubic units.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IXOGEG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $23$ feet and a width of $14$ feet. What is the area, in square feet, of the garden?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '322', ARRAY['322'], E'The area of a rectangle is length times width: $23 \\times 14 = 322$ square feet.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J8ILT7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 13x - 47$. What is the value of $f(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$31$"},{"key":"B","text":"$125$"},{"key":"C","text":"$-31$"},{"key":"D","text":"$78$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 6$: $f(6) = 13(6) - 47 = 78 - 47 = 31$. The value $125$ results from an arithmetic slip, adding $47$ to $78$ instead of subtracting. The value $-31$ comes from a sign error, computing $47 - 78$ instead of $78 - 47$. The value $78$ is the result of partial reasoning — computing $13 \\times 6$ but omitting the subtraction of $47$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L3P75H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally costs $\\$47$. During a sale, the price is reduced by $30\\%$. What is the sale price of the shirt?', NULL, $lyceon_json$[{"key":"A","text":"$\\$14.10$"},{"key":"B","text":"$\\$32.90$"},{"key":"C","text":"$\\$52.50$"},{"key":"D","text":"$\\$61.10$"}]$lyceon_json$::jsonb, 'B', NULL, E'A $30\\%$ discount means the sale price is $70\\%$ of the original: $47 \\times 0.70 = \\$32.90$. The distractor $\\$14.10$ gives the discount amount ($47 \\times 0.30$) rather than the sale price. The distractor $\\$52.50$ results from an arithmetic miscalculation. The distractor $\\$61.10$ results from adding $30\\%$ to the original price ($47 \\times 1.30$) instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L9NQFO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $DEF$, the right angle is at $E$, $DE = 7$, and $EF = 24$. What is the value of $\\sin(F)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{25}$"},{"key":"B","text":"$\\frac{24}{25}$"},{"key":"C","text":"$\\frac{7}{24}$"},{"key":"D","text":"$\\frac{25}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The hypotenuse is $DF = \\sqrt{7^2 + 24^2} = \\sqrt{49 + 576} = \\sqrt{625} = 25$. Angle $F$ is at vertex $F$. The side opposite angle $F$ is $DE = 7$, and the hypotenuse is $25$. So $\\sin(F) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{7}{25}$. The distractor $\\frac{24}{25}$ uses the adjacent side instead of the opposite side, computing cosine rather than sine. The distractor $\\frac{7}{24}$ uses the adjacent side in the denominator instead of the hypotenuse, computing tangent. The distractor $\\frac{25}{7}$ inverts the sine ratio, computing cosecant instead of sine.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LJW67X', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $9x - 4y = 36$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -9)$"},{"key":"B","text":"$(0, 9)$"},{"key":"C","text":"$(0, 4)$"},{"key":"D","text":"$(0, 36)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x = 0$: $9(0) - 4y = 36$, so $-4y = 36$ and $y = -9$. The $y$-intercept is $(0, -9)$. The answer $(0, 9)$ reflects a sign error when dividing $36$ by $-4$. The answer $(0, 4)$ confuses the coefficient of $y$ with the intercept value, a concept gap. The answer $(0, 36)$ mistakes the constant on the right side for the $y$-intercept, misreading what the question requires.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M6AKRM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $h$ is defined by $h(x) = x^2 - 8x + 23$. What is the minimum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$7$"},{"key":"C","text":"$23$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $h(x) = x^2 - 8x + 23 = (x - 4)^2 - 16 + 23 = (x - 4)^2 + 7$. Since $(x - 4)^2 \\geq 0$, the minimum value is $7$, occurring at $x = 4$. The distractor $4$ is the $x$-value where the minimum occurs, not the minimum value itself. The distractor $23$ is the constant term of the original expression (the $y$-intercept), not the minimum. The distractor $-7$ applies a sign error to the correct minimum value.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NB4MYQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands $83$ meters from the base of a building and measures the angle of elevation to the top of the building as $59^\\circ$. The surveyor then walks $37$ meters closer to the building and measures the angle of elevation again. Which expression gives the tangent of this second angle of elevation?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{83\\tan(59^\\circ)}{46}$"},{"key":"B","text":"$\\frac{83\\tan(59^\\circ)}{37}$"},{"key":"C","text":"$\\frac{46\\tan(59^\\circ)}{83}$"},{"key":"D","text":"$\\frac{83}{46\\tan(59^\\circ)}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The height of the building is $h = 83\\tan(59^\\circ)$. After walking $37$ meters closer, the new distance from the base is $83 - 37 = 46$ meters. The tangent of the second angle is $\\frac{h}{46} = \\frac{83\\tan(59^\\circ)}{46}$. The distractor $\\frac{83\\tan(59^\\circ)}{37}$ uses the distance walked ($37$) as the new distance from the building instead of computing $83 - 37 = 46$. The distractor $\\frac{46\\tan(59^\\circ)}{83}$ incorrectly uses the new distance in the numerator and old distance in the denominator, reversing the relationship. The distractor $\\frac{83}{46\\tan(59^\\circ)}$ inverts the tangent relationship entirely, placing the height in the denominator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OFDFM4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x + 3y = 17$. Line $q$ is perpendicular to line $p$ and passes through the point $(4, -1)$. What is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$y = \\frac{3}{5}x - \\frac{17}{5}$"},{"key":"B","text":"$y = -\\frac{5}{3}x + \\frac{17}{3}$"},{"key":"C","text":"$y = \\frac{5}{3}x - \\frac{23}{3}$"},{"key":"D","text":"$y = -\\frac{3}{5}x + \\frac{7}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $p$: $3y = -5x + 17$, so $y = -\\frac{5}{3}x + \\frac{17}{3}$, giving slope $-\\frac{5}{3}$. The perpendicular slope is $\\frac{3}{5}$. Using point-slope with $(4, -1)$: $y + 1 = \\frac{3}{5}(x - 4)$, so $y = \\frac{3}{5}x - \\frac{12}{5} - 1 = \\frac{3}{5}x - \\frac{17}{5}$. The option $y = -\\frac{5}{3}x + \\frac{17}{3}$ uses the original slope instead of the perpendicular reciprocal, a concept gap. The option $y = \\frac{5}{3}x - \\frac{23}{3}$ uses the reciprocal without negating, a sign error. The option $y = -\\frac{3}{5}x + \\frac{7}{5}$ negates the perpendicular slope incorrectly, an equation setup error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OHCEY2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $g$ is defined by $g(x) = 2(x - 3)^2 - 11$. If $g(a) = g(7)$ and $a \\neq 7$, what is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1', ARRAY['-1'], E'First compute $g(7) = 2(7 - 3)^2 - 11 = 2(16) - 11 = 32 - 11 = 21$. The parabola $g(x) = 2(x - 3)^2 - 11$ has its axis of symmetry at $x = 3$. Since $7$ is $4$ units to the right of the axis, the other $x$-value with the same output is $4$ units to the left: $a = 3 - 4 = -1$. This can be verified: $g(-1) = 2(-1 - 3)^2 - 11 = 2(16) - 11 = 21 = g(7)$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ONBK0M', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A taxi company charges a base fare of $\\$3.70$ plus $\\$0.85$ per mile traveled. The total fare $f$, in dollars, for a trip of $m$ miles is given by the function $f(m) = 0.85m + 3.70$. What is the best interpretation of the number $0.85$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The total fare for a $1$-mile trip"},{"key":"B","text":"The increase in total fare, in dollars, for each additional mile traveled"},{"key":"C","text":"The base fare charged before any miles are traveled"},{"key":"D","text":"The total number of miles included in the base fare"}]$lyceon_json$::jsonb, 'B', NULL, E'In the function $f(m) = 0.85m + 3.70$, the coefficient $0.85$ is the rate of change — the amount the fare increases for each additional mile. The interpretation as the total fare for a $1$-mile trip confuses the slope with a specific output value (a concept gap, since $f(1) = 4.55$, not $0.85$). The interpretation as the base fare confuses the slope with the $y$-intercept, misreading the question. The interpretation as miles included in the base fare confuses a dollar rate with a distance quantity, an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OZW9NA', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{3(2x - 7)}{4} + 5 = 11$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7.5', ARRAY['15/2', '7.5'], E'Subtract $5$ from both sides: $\\frac{3(2x - 7)}{4} = 6$. Multiply both sides by $4$: $3(2x - 7) = 24$. Divide both sides by $3$: $2x - 7 = 8$. Add $7$: $2x = 15$. Divide by $2$: $x = 7.5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R4G3DJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'A box contains 41 tokens. Each token is labeled with exactly one color: 17 are red, 11 are blue, and 13 are green. Each token is also marked as either a star or a circle. Of the red tokens, 9 are stars. Of the blue tokens, 4 are stars. Of the green tokens, 7 are stars. Two tokens are selected at random without replacement. Given that the first token selected is a blue star, what is the probability that the second token selected is also a star? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19/40', ARRAY['19/40', '0.475', '.475'], E'The total number of star tokens is $9 + 4 + 7 = 20$. After one blue star is removed, there are $20 - 1 = 19$ star tokens remaining out of $41 - 1 = 40$ total tokens. Therefore the conditional probability that the second token is a star is $\\frac{19}{40}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RB2RXQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A plumber charges a flat fee of $\\$47$ for a service call plus $\\$31$ per hour of labor. An electrician charges a flat fee of $\\$83$ plus $\\$22$ per hour. For how many hours of work would both professionals charge the same total amount?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the two costs equal: $47 + 31h = 83 + 22h$. Subtracting $22h$ from both sides gives $47 + 9h = 83$. Subtracting $47$ gives $9h = 36$, so $h = 4$. The value $3$ results from an arithmetic slip in the subtraction step. The value $5$ comes from setting up the equation incorrectly, such as reversing which rate belongs to which professional. The value $6$ comes from partial reasoning, such as only computing the difference in flat fees ($36$) but dividing by a wrong rate difference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
