INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SMJ8ZV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $MNP$, the measure of angle $M$ is $47^\\circ$ and the measure of angle $N$ is $71^\\circ$. What is the measure, in degrees, of angle $P$?', NULL, $lyceon_json$[{"key":"A","text":"$52$"},{"key":"B","text":"$62$"},{"key":"C","text":"$72$"},{"key":"D","text":"$118$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Therefore angle $P = 180 - 47 - 71 = 62^\\circ$. The value $52$ results from an arithmetic slip, such as computing $180 - 47 - 71$ as $180 - 128 = 52$ instead of $180 - 118 = 62$. The value $72$ arises from misreading $71$ as $61$ or from confusing the computation steps. The value $118$ is the sum of the two given angles ($47 + 71 = 118$), reflecting a concept gap where the student adds the given angles instead of subtracting their sum from $180$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TKTP71', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, side $AB = 11$, side $BC = 7$, and side $AC = 13$. Point $D$ lies on segment $AC$ such that $BD$ bisects angle $B$. What is the length of $AD$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{143}{18}$"},{"key":"B","text":"$\\frac{91}{18}$"},{"key":"C","text":"$\\frac{11}{2}$"},{"key":"D","text":"$\\frac{13}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the angle bisector theorem, the bisector from $B$ to $D$ on $AC$ divides $AC$ in the ratio $AB:BC = 11:7$. So $\\frac{AD}{DC} = \\frac{11}{7}$. Since $AD + DC = 13$, we have $AD = \\frac{11}{18} \\times 13 = \\frac{143}{18}$. The distractor $\\frac{91}{18}$ applies the ratio in reverse, computing $DC = \\frac{7}{18} \\times 13 = \\frac{91}{18}$ and reporting it as $AD$. The distractor $\\frac{11}{2}$ assumes $D$ is simply the midpoint scaled by side ratios, reflecting a conceptual misunderstanding. The distractor $\\frac{13}{2}$ assumes $D$ is the midpoint of $AC$, ignoring the angle bisector constraint entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
