INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U1GIDK', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{9x^2 - 4}{3x - 2} \\cdot \\frac{x^2 - 11x + 28}{3x^2 - 10x - 8}$ can be written in the form $ax + b$ for all values of $x$ where the expression is defined. What is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-6', ARRAY['-6'], E'Factor each component. $9x^2 - 4 = (3x - 2)(3x + 2)$ is a difference of squares. $x^2 - 11x + 28 = (x - 4)(x - 7)$ since $(-4)(-7) = 28$ and $-4 + (-7) = -11$. $3x^2 - 10x - 8 = (3x + 2)(x - 4)$ since $(3x + 2)(x - 4) = 3x^2 - 12x + 2x - 8 = 3x^2 - 10x - 8$. The expression becomes $\\frac{(3x - 2)(3x + 2)}{3x - 2} \\cdot \\frac{(x - 4)(x - 7)}{(3x + 2)(x - 4)}$. Canceling $(3x - 2)$, $(3x + 2)$, and $(x - 4)$ leaves $x - 7$. So $a = 1$ and $b = -7$, giving $a + b = 1 + (-7) = -6$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V6PS21', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'A right triangle has legs of length $9$ and $40$. What is the length of the hypotenuse?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '41', ARRAY['41'], E'Using the Pythagorean theorem: $c = \\sqrt{9^2 + 40^2} = \\sqrt{81 + 1600} = \\sqrt{1681} = 41$. The hypotenuse is $41$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VADAKM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A researcher surveyed a random sample of 400 registered voters in a city and found that $53\\%$ support a proposed park renovation. The margin of error for this estimate is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $53\\%$ of all registered voters in the city support the renovation."},{"key":"B","text":"Between $49\\%$ and $57\\%$ of all registered voters in the city likely support the renovation."},{"key":"C","text":"Between $49\\%$ and $57\\%$ of the 400 sampled voters support the renovation."},{"key":"D","text":"The survey result could be off by as much as $53\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of 4 percentage points means the plausible range for the true population proportion is $53\\% \\pm 4\\%$, or between $49\\%$ and $57\\%$, so the interval applies to all registered voters, not just the sample. The distractor stating exactly $53\\%$ ignores sampling variability entirely. The distractor applying the interval to the sampled voters confuses the sample statistic (which is known exactly) with the population parameter being estimated. The distractor claiming the result could be off by $53\\%$ confuses the sample proportion with the margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VS9O7B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the relationship between the age of a tree in years ($x$) and its trunk diameter in inches ($y$) using the equation $y = 0.47x + 1.9$. For a tree that is $14$ years old, the actual trunk diameter is $9.2$ inches. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-0.72$"},{"key":"B","text":"$0.72$"},{"key":"C","text":"$8.48$"},{"key":"D","text":"$17.68$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted value is $y = 0.47(14) + 1.9 = 6.58 + 1.9 = 8.48$ inches. The residual is actual minus predicted: $9.2 - 8.48 = 0.72$. The distractor $-0.72$ results from computing predicted minus actual ($8.48 - 9.2$), reversing the residual formula. The distractor $8.48$ gives the predicted value itself rather than the difference between actual and predicted. The distractor $17.68$ results from adding the actual and predicted values ($9.2 + 8.48$) instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VU7LX4', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{4x^3 - 18x^2 + 14x}{2x}$ for all $x \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^2 - 9x + 7$"},{"key":"B","text":"$2x^2 - 9x + 14$"},{"key":"C","text":"$4x^2 - 18x + 14$"},{"key":"D","text":"$2x^3 - 9x^2 + 7x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing each term by $2x$: $\\frac{4x^3}{2x} = 2x^2$, $\\frac{-18x^2}{2x} = -9x$, and $\\frac{14x}{2x} = 7$, giving $2x^2 - 9x + 7$. The distractor $2x^2 - 9x + 14$ correctly divides the first two terms but only divides $14x$ by $x$ (not by $2x$), leaving $14$ instead of $7$. The distractor $4x^2 - 18x + 14$ divides each term only by $x$, neglecting the factor of $2$ in the denominator. The distractor $2x^3 - 9x^2 + 7x$ divides only the coefficients by $2$ without reducing the powers of $x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
