INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XGW5BP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $f$ is defined by $f(x) = a \\cdot 4^{bx}$, where $a$ and $b$ are positive constants. If $f(3) = 48$ and $f(9) = 3072$, what is the value of $f(6)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '384', ARRAY['384'], E'From the function definition, $f(3) = a \\cdot 4^{3b} = 48$ and $f(9) = a \\cdot 4^{9b} = 3072$. Dividing the second equation by the first: $\\frac{a \\cdot 4^{9b}}{a \\cdot 4^{3b}} = 4^{6b} = \\frac{3072}{48} = 64$. Since $64 = 4^3$, we have $6b = 3$, so $b = \\frac{1}{2}$. Substituting back: $a \\cdot 4^{3/2} = a \\cdot 8 = 48$, giving $a = 6$. Therefore $f(6) = 6 \\cdot 4^{6 \\cdot (1/2)} = 6 \\cdot 4^3 = 6 \\cdot 64 = 384$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YL2WO5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $41^\\circ$ and the measure of angle $Q$ is $67^\\circ$. An exterior angle is formed at vertex $R$. What is the measure, in degrees, of this exterior angle?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$108$"},{"key":"C","text":"$139$"},{"key":"D","text":"$113$"}]$lyceon_json$::jsonb, 'B', NULL, E'The interior angle at $R$ is $180 - 41 - 67 = 72^\\circ$. The exterior angle at $R$ is supplementary to the interior angle: $180 - 72 = 108^\\circ$. Equivalently, the exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $41 + 67 = 108$. The distractor $72$ is the interior angle at $R$, representing a partial solution that stops before finding the exterior angle. The distractor $139$ comes from an arithmetic error such as misapplying $180 - 41 = 139$, using only one remote interior angle. The distractor $113$ comes from an incorrect setup, such as averaging the supplement and sum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YLVSIO', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A small business owner can produce at most $130$ items per week using two machines. Machine A produces $a$ items and Machine B produces $b$ items, where $a \\geq 0$ and $b \\geq 0$. The profit per item from Machine A is $\\$9$ and from Machine B is $\\$11$. If the owner requires at least $\\$1{,}100$ in weekly profit, which system of inequalities describes the feasible region?', NULL, $lyceon_json$[{"key":"A","text":"$a + b \\leq 130,\\; 9a + 11b \\geq 1{,}100$"},{"key":"B","text":"$a + b \\geq 130,\\; 9a + 11b \\geq 1{,}100$"},{"key":"C","text":"$a + b \\leq 130,\\; 9a + 11b \\leq 1{,}100$"},{"key":"D","text":"$a + b \\leq 130,\\; 11a + 9b \\geq 1{,}100$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total production cannot exceed $130$ items, so $a + b \\leq 130$. The profit must be at least $\\$1{,}100$, so $9a + 11b \\geq 1{,}100$. Writing $a + b \\geq 130$ incorrectly requires producing at least $130$ items rather than at most. Writing $9a + 11b \\leq 1{,}100$ reverses the profit constraint to cap profit instead of requiring a minimum. Writing $11a + 9b \\geq 1{,}100$ swaps the profit coefficients between the two machines, assigning $\\$11$ per item to Machine A and $\\$9$ to Machine B.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZQGHOA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'The population of a city was $6{,}700$ in 2018. By 2022, the population had increased to $7{,}891$. What is the percent increase in the population from 2018 to 2022, to the nearest tenth? (Do not include the percent sign.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17.8', ARRAY['89/5', '17.8'], E'The increase in population is $7{,}891 - 6{,}700 = 1{,}191$. The percent increase is $\\frac{1{,}191}{6{,}700} \\times 100 = 17.776\\ldots\\%$, which rounds to $17.8\\%$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZYC3U6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A car travels $203$ miles using $7$ gallons of gasoline. A truck uses gasoline at a rate, in gallons per mile, that is $\\frac{3}{2}$ times the rate of the car. How many gallons of gasoline would the truck use to travel $174$ miles?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'The car''s fuel consumption rate is $\\frac{7}{203}$ gallons per mile. The truck''s rate is $\\frac{3}{2} \\times \\frac{7}{203} = \\frac{21}{406} = \\frac{3}{58}$ gallons per mile. For $174$ miles, the truck uses $174 \\times \\frac{3}{58} = \\frac{522}{58} = 9$ gallons.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2057BOZ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The textile fragments recovered from the Pazyryk burial mounds—frozen for over 2,400 years in the permafrost of the Altai _______ display weaving techniques that scholars had not expected to find outside of ancient Mesopotamian workshops.', $lyceon_json$[{"key":"A","text":"Mountains, display"},{"key":"B","text":"Mountains; display"},{"key":"C","text":"Mountains—display"},{"key":"D","text":"Mountains—, display"}]$lyceon_json$::jsonb, 'C', NULL, E'The phrase "frozen for over 2,400 years in the permafrost of the Altai Mountains" is a parenthetical inserted into the main clause "The textile fragments recovered from the Pazyryk burial mounds display weaving techniques..." The opening em dash before "frozen" must be matched by a closing em dash after "Mountains," making "Mountains—display" the correct choice. A comma after "Mountains" fails to match the opening dash and creates an asymmetric punctuation pair. A semicolon after "Mountains" incorrectly splits the sentence; removing the parenthetical would leave "The textile fragments...display weaving techniques," which is a single clause that cannot be divided by a semicolon. Combining a dash with a comma ("Mountains—, display") introduces redundant punctuation—the closing dash alone closes the parenthetical, and no additional comma is needed or permitted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21PHAH5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architect who designed the cantilevered observation deck extending over the gorge insisted that the structure''s load-bearing _______ tested under conditions simulating wind speeds of up to 170 kilometers per hour before the facility opened to visitors.', $lyceon_json$[{"key":"A","text":"columns are"},{"key":"B","text":"columns be"},{"key":"C","text":"columns would be"},{"key":"D","text":"columns have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The verb "insisted" in the sense of making a demand triggers the mandative subjunctive in the "that" clause. The subjunctive requires the bare form of the verb—"be"—regardless of subject number, making "columns be" the correct choice. The indicative "columns are" fails to use the subjunctive mood required after verbs of demand such as "insisted." The conditional "columns would be" introduces an unnecessary and non-standard modal; the mandative subjunctive after "insisted that" does not permit "would." The present perfect "columns have been" is in the wrong mood entirely, treating the clause as an indicative statement rather than a demand.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2346G0V', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurately cited, would best support the student''s claim?', E'A student argues that Octavia Butler''s novel Kindred (1979) deliberately resists the conventions of traditional science fiction by refusing to provide any technological or scientific explanation for its protagonist''s time travel. Instead, the student claims, Butler uses the unexplained mechanism as a literary device to foreground the emotional and historical realities of American slavery over speculative world-building.', $lyceon_json$[{"key":"A","text":"\"Butler's omission of a time-travel apparatus is not a gap in craft but a calculated refusal to let genre machinery distract from the bodily horror Dana experiences on the Weylin plantation.\""},{"key":"B","text":"\"Kindred stands as Butler's most commercially successful novel, reaching audiences well beyond the traditional science fiction readership that sustained her earlier works.\""},{"key":"C","text":"\"The lack of a time-travel explanation in Kindred reflects Butler's relative inexperience with hard science fiction conventions at that stage of her career.\""},{"key":"D","text":"\"Butler's debt to H.G. Wells's The Time Machine is evident in Kindred's structure, which follows Wells's template of a protagonist involuntarily displaced through time.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The student claims Butler intentionally omits a scientific explanation for time travel in order to center the historical realities of slavery. The quotation describing Butler''s omission as a ''calculated refusal'' to let genre machinery distract from Dana''s experience directly supports both the intentionality and the purpose the student identifies. The quotation about commercial success addresses the novel''s reception rather than Butler''s deliberate narrative choices. The quotation attributing the omission to inexperience contradicts the student''s claim that the lack of explanation was deliberate rather than accidental. The quotation about debt to H.G. Wells frames Kindred as following science fiction conventions rather than resisting them, which opposes the student''s argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
