INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23HVEKR', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a museum exhibit about traditional Korean ceramics. The student wants to emphasize the global significance of Goryeo celadon pottery. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23J97CE', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'During the early twentieth century, the Argentine composer Alberto Ginastera drew extensively on folk melodies from the Pampas region. His integration of these motifs into orchestral works was not merely decorative; rather, it was a deliberate effort to ______ the cultural identity of rural Argentina within the classical music tradition.', $lyceon_json$[{"key":"A","text":"embed"},{"key":"B","text":"fracture"},{"key":"C","text":"delay"},{"key":"D","text":"audit"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Ginastera''s deliberate effort to place rural Argentine cultural identity into the classical tradition. "Embed" means to fix firmly within a surrounding context, which precisely matches this idea of integrating folk identity into orchestral works. "Fracture" means to break apart, which contradicts the passage''s emphasis on integration. "Delay" means to postpone, which is irrelevant to the act of incorporating cultural identity. "Audit" means to examine or inspect, which does not fit the context of placing cultural elements within a tradition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW247HCSD', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the paleontologists who first excavated the fossil bed in 2017 nor the geochemist who later analyzed the surrounding _______ able to explain how a marine reptile species previously found only in Cretaceous deposits of western Morocco came to be preserved in a landlocked formation in central Mongolia.', $lyceon_json$[{"key":"A","text":"sediment were"},{"key":"B","text":"sediment are"},{"key":"C","text":"sediment was"},{"key":"D","text":"sediment has been"}]$lyceon_json$::jsonb, 'C', NULL, E'In a "neither...nor" construction, the verb agrees in number with the nearer subject. The nearer subject here is "the geochemist," which is singular, so the singular past-tense "was" is correct: "nor the geochemist...was able to explain." The plural "were" incorrectly agrees with the more distant subject "paleontologists" rather than the nearer "geochemist." The present-tense plural "are" fails on both tense (the excavation and analysis occurred in the past, as indicated by "first excavated...in 2017" and "later analyzed") and number. The present perfect singular "has been" uses the wrong tense for a completed past-tense narrative; the events described are situated in a defined past time frame, which requires simple past.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24QR23H', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Freiburg have found that the European garden spider (Araneus diadematus) adjusts the tension of its web silk in response to wind conditions. In calm environments, the spiders produce looser webs that maximize surface area for prey capture. However, when exposed to sustained winds exceeding 11 kilometers per hour, the spiders tighten individual radial threads by as much as 37 percent, sacrificing capture area to prevent structural failure. The researchers noted that this tension adjustment occurs during web construction, not after completion, indicating that the spiders detect wind speed and preemptively modify their building behavior rather than repairing damage after the fact.', $lyceon_json$[{"key":"A","text":"European garden spiders modify web tension during construction based on wind conditions to balance prey capture and structural integrity."},{"key":"B","text":"Spiders at the University of Freiburg were studied to determine the maximum wind speed their webs could withstand before breaking."},{"key":"C","text":"European garden spiders have evolved the ability to repair damaged webs more efficiently than other arachnid species."},{"key":"D","text":"Wind speeds above 11 kilometers per hour cause all spider webs to lose approximately 37 percent of their structural capacity."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centrally describes how European garden spiders preemptively adjust web tension during construction in response to wind, balancing capture area against structural integrity. The option stating that spiders modify web tension during construction based on wind conditions captures this main idea. The option about studying maximum wind speed misreads the study''s purpose -- the researchers examined tension adjustment behavior, not breakage thresholds. The option about repairing damaged webs contradicts the passage, which explicitly states that adjustments occur during construction rather than as post-damage repairs. The option claiming all spider webs lose 37 percent structural capacity overgeneralizes a detail about thread tightening in one species to all spiders and mischaracterizes the statistic.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26O3AXX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an article for a science magazine. The student wants to challenge the assumption that cephalopod intelligence is primarily visual by highlighting evidence of non-visual cognitive abilities. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29G7GC1', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Volcanologist Kenji Murakami''s survey of seventeen Pacific Rim calderas identified three that warrant immediate monitoring: Mount Pinatubo in the _______ Taal, also in the Philippines, which has shown increasing seismic activity; and Sakurajima in southern Japan, where lava dome growth has accelerated since 2019.', $lyceon_json$[{"key":"A","text":"Philippines, Taal"},{"key":"B","text":"Philippines: Taal"},{"key":"C","text":"Philippines. Taal"},{"key":"D","text":"Philippines; Taal"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence presents a colon-introduced list of three calderas whose individual descriptions contain internal commas ("Taal, also in the Philippines, which has shown increasing seismic activity" and "Sakurajima in southern Japan, where lava dome growth has accelerated since 2019"). When list items contain internal commas, semicolons must separate the items to prevent ambiguity, making "Philippines; Taal" the correct choice. A comma after "Philippines" would blend into the internal commas of the next item, creating confusion about where one item ends and another begins. A colon after "Philippines" would nest a second colon inside the list already introduced by a colon, which is non-standard. A period after "Philippines" would break the colon-introduced list into separate sentences, severing the grammatical structure that ties the three calderas to "identified three that warrant immediate monitoring."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D61GK5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason the Nabataeans'' agricultural methods were effective in the Negev Desert?', E'The Nabataeans, who inhabited the Negev Desert from roughly the 4th century BCE to the 2nd century CE, developed an agricultural system that scholars long considered implausible for such an arid region. Recent archaeological work by Haiman and Fabian has clarified the mechanism: the Nabataeans constructed elaborate networks of low stone walls, or terrace channels, across hillsides to direct rare flash-flood runoff into cultivated plots in valley floors. Crucially, the soil in these plots was not natural but engineered -- compacted layers of loess mixed with calcium-richite fragments that created a moisture-retaining substrate capable of sustaining barley and wheat through the seven-to-nine-month dry interval. A single 40-minute storm could saturate these prepared plots deeply enough to support an entire growing cycle, which explains how the Nabataeans fed a population estimated at 30,000 in an area receiving fewer than 90 millimeters of annual rainfall.', $lyceon_json$[{"key":"A","text":"They traded extensively with neighboring civilizations to import grain during dry periods."},{"key":"B","text":"They channeled scarce floodwater into engineered soil plots that retained moisture across long dry intervals."},{"key":"C","text":"They developed drought-resistant crop varieties specifically adapted to receiving fewer than 90 millimeters of rainfall."},{"key":"D","text":"They relocated their population seasonally to follow shifting rainfall patterns across the Negev region."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explains that the Nabataeans'' system worked by directing flash-flood runoff through terrace channels into valley plots containing engineered, moisture-retaining soil -- the option about channeling floodwater into engineered soil plots captures both elements. The option about trading for imported grain introduces an activity never mentioned in the passage. The option about drought-resistant crop varieties is unsupported; the passage mentions barley and wheat without describing them as specially developed cultivars. The option about seasonal relocation contradicts the passage''s description of a stationary agricultural infrastructure with permanent terrace walls and prepared plots.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E5XOO9', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Emeka Osei-Mensah argues that the Kingdom of Dahomey''s female military regiment, the Mino, were not merely ceremonial guards but a decisive tactical force. He cites the 1851 siege of Abeokuta, where a contingent of approximately 6,000 Mino soldiers formed the primary assault column. _______ Osei-Mensah acknowledges that Dahomean oral traditions may have inflated the regiment''s numbers, he maintains that even conservative estimates of 2,500 to 3,000 active Mino fighters confirm their central military role rather than a symbolic one.', $lyceon_json$[{"key":"A","text":"Although"},{"key":"B","text":"Moreover,"},{"key":"C","text":"In particular,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence after the blank has a two-part structure: it concedes a potential weakness in the evidence (inflated numbers in oral traditions) before reasserting the historian''s main claim (the Mino were a central military force). "Although" correctly introduces this concession-assertion structure by signaling that what follows is a qualification that does not ultimately undermine the argument. "Moreover," incorrectly signals additional supporting evidence, failing to capture the concessive move in which the historian admits a limitation before reaffirming his position. "In particular," wrongly suggests the sentence provides a specific example of the preceding point, when it actually introduces a complication to the evidence just cited. "Consequently," incorrectly implies the concession about inflated numbers follows as a direct result of the 1851 siege data, when the relationship is one of qualification, not causation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ELL2YS', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Tara Nakamura has spent over a decade cataloging bioluminescent organisms in the Celebes Sea. Her team identified 37 previously undocumented species of light-producing jellyfish between 2019 and 2024. _______ Nakamura''s findings have prompted the Philippine government to designate a 4,100-square-kilometer protected zone around the deepwater trenches where many of these species were discovered.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"As a result,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Nakamura''s discovery of 37 undocumented species, and the sentence that follows describes a government action taken because of those findings. The relationship is cause-and-effect, so "As a result," is the correct transition. "In other words," incorrectly signals a restatement, when the second sentence introduces new information (a government designation) rather than rephrasing the discovery. "In contrast," wrongly signals opposition, but the government''s protective response is consistent with, not opposed to, the discovery. "Meanwhile," incorrectly signals simultaneous but unrelated events, when the passage clearly presents the government action as a direct consequence of the research.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GZX5GY', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from Okafor''s study, if accurate, would most effectively undermine the conclusion drawn by the municipal planning board?', E'After reviewing a decade of transit ridership data, the Bellworth Municipal Planning Board concluded that the city''s 2019 expansion of protected bicycle lanes along its three busiest corridors caused a measurable decline in public bus ridership, which fell 14 percent between 2019 and 2023. The board cited this decline as evidence that bicycle infrastructure diverts commuters away from mass transit, and recommended against further bicycle lane construction. However, transportation researcher Adaeze Okafor has noted that the board''s analysis did not account for several concurrent changes during the same period, including a fare restructuring in 2020 and the relocation of two major employers outside the city center in 2021.', $lyceon_json$[{"key":"A","text":"In cities that expanded bicycle lanes without simultaneously restructuring fares or experiencing employer relocations, bus ridership remained stable or increased slightly during the same period."},{"key":"B","text":"Bellworth residents who began cycling after 2019 predominantly shifted from private automobile commutes rather than from bus ridership."},{"key":"C","text":"Protected bicycle lanes in Bellworth reduced traffic accident rates by 22 percent along the three corridors where they were installed."},{"key":"D","text":"Bellworth's bus fleet was expanded by 15 percent in 2020 to accommodate anticipated ridership growth from the city's population increase."}]$lyceon_json$::jsonb, 'A', NULL, E'The board concluded that bicycle lanes caused the ridership decline, but Okafor noted uncontrolled confounders (fare changes, employer relocations). The finding that cities with bicycle lane expansion but without those confounders saw stable or increased bus ridership directly undermines the board''s causal claim by isolating the variable. The finding about cyclists shifting from cars rather than buses is relevant but only partially undermines the board -- it addresses mode-shift composition without ruling out that some bus riders also switched, making it less effective than a controlled comparison. The finding about reduced accident rates addresses safety rather than the ridership question. The finding about fleet expansion addresses transit supply, not the causal relationship between bicycle lanes and ridership demand.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HMAVEJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the New Zealand nikau palm (Rhopalostylis sapida) takes over twelve months to ripen, an unusually long maturation period compared to most temperate palms. During this time, the fruit transitions from bright green to deep red -- a color shift that coincides with peak activity of the kereru, a large native pigeon and the nikau''s primary seed disperser. Since kereru are strongly attracted to red-spectrum fruits and largely ignore green ones, the nikau''s extended ripening period ensures that seeds are not dispersed prematurely into unfavorable germination conditions. Instead, ________', $lyceon_json$[{"key":"A","text":"the fruit drops to the forest floor before any bird species can consume it."},{"key":"B","text":"the seeds reach maturity before being ingested and transported by kereru to new locations."},{"key":"C","text":"kereru populations have declined due to the difficulty of locating ripe nikau fruit."},{"key":"D","text":"the nikau palm has developed a chemical defense to prevent all frugivory during the green stage."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explains that the nikau''s color shift from green to red aligns with kereru activity and that the extended ripening prevents premature dispersal. The logical completion is that seeds reach maturity before kereru consume and transport them. The option about fruit dropping before consumption contradicts the passage''s emphasis on kereru as the primary seed disperser. The option about declining kereru populations introduces a negative consequence unsupported by the passage. The option about chemical defense introduces a mechanism the passage never mentions -- it describes color-based timing, not chemical deterrence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IJ82QL', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a cornerstone of genetics research for over a century. Its short generation time, well-mapped genome, and ease of laboratory maintenance make it an exceptionally practical model organism. <u>However, fruit flies diverged from the mammalian lineage approximately 600 million years ago, and many genes that regulate human disease processes have no direct counterpart in the Drosophila genome.</u> For this reason, researchers studying conditions such as Alzheimer''s disease increasingly supplement fly-based experiments with work in mouse models.', $lyceon_json$[{"key":"A","text":"It identifies a limitation that motivates the shift in research approach described afterward."},{"key":"B","text":"It provides historical background on the discovery of Drosophila as a model organism."},{"key":"C","text":"It lists specific diseases that cannot be studied using any insect model."},{"key":"D","text":"It challenges the claim that Drosophila has a well-mapped genome."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence introduces a constraint — the evolutionary distance between fruit flies and mammals — that explains why researchers turn to mouse models, as described in the final sentence. Thus it identifies a limitation motivating the shift in approach. The choice claiming historical background is incorrect because the sentence discusses evolutionary divergence, not the history of Drosophila''s discovery. The choice about listing diseases that cannot be studied using insects misreads the passage: the text mentions Alzheimer''s disease as an example of supplementing fly work, not as proof that insect models are entirely unusable. The choice about challenging the genome-mapping claim is wrong because the sentence does not dispute that the genome is well-mapped; it raises a separate issue about gene correspondence across species.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J1HD49', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the two texts characterize the role of fire in forest ecosystems?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J79OAF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'The philosopher Hannah Arendt distinguished sharply between labor, work, and action as three fundamental human activities. Labor, in her account, encompasses the biological processes necessary for survival — eating, sleeping, and bodily maintenance — activities that leave no lasting product. Work, by contrast, fabricates the durable objects that constitute the human-built world: tables, buildings, artworks. Arendt reserved the term ''action'' for the capacity to initiate something genuinely new through speech and deed in the public realm, an activity she considered uniquely political and irreducible to either labor or work.', $lyceon_json$[{"key":"A","text":"It presents a philosopher's tripartite framework by defining each category and distinguishing it from the others."},{"key":"B","text":"It traces the historical evolution of a philosopher's thinking from her early career to her final publications."},{"key":"C","text":"It argues that one of the three categories identified by a philosopher is more important than the other two."},{"key":"D","text":"It contrasts two competing philosophical interpretations of human activity and endorses one over the other."}]$lyceon_json$::jsonb, 'A', NULL, E'The text systematically introduces Arendt''s three categories — labor, work, and action — defining each in turn and clarifying how it differs from the others. This matches the description of presenting a tripartite framework with definitions and distinctions. The choice about tracing historical evolution is incorrect because the passage does not discuss changes in Arendt''s thinking over time. The choice claiming the text argues one category is more important misreads the passage: while Arendt describes action as "uniquely political," the text presents this as part of her framework rather than arguing for its superiority. The choice about contrasting two competing interpretations is wrong because the text presents only Arendt''s single framework, not a debate between rival philosophers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JG634J', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After three decades of excavation in southern Turkey, archaeologist Elif Karakuş reached a conclusion that surprised many of her _______ the settlement''s inhabitants had not abandoned the site because of warfare, as previously theorized, but because a prolonged drought had depleted the surrounding aquifer beyond recovery.', $lyceon_json$[{"key":"A","text":"colleagues, the"},{"key":"B","text":"colleagues: the"},{"key":"C","text":"colleagues the"},{"key":"D","text":"colleagues; and the"}]$lyceon_json$::jsonb, 'B', NULL, E'The second part of the sentence specifies the content of the conclusion, so a colon is the correct punctuation to introduce that elaboration. "Colleagues: the" properly signals that what follows is the conclusion itself. The comma option ("colleagues, the") creates a comma splice, joining two independent clauses with only a comma. The option with no punctuation ("colleagues the") produces a run-on sentence. The semicolon-plus-"and" option ("colleagues; and the") is illogical because the second clause is not an additional independent thought—it is the substance of the conclusion mentioned in the first clause, and "and" misrepresents that relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K90PTD', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'In 1847, the Hungarian physician Ignaz Semmelweis observed that the mortality rate from puerperal fever in the maternity ward staffed by medical students was nearly five times higher than in the ward staffed by midwives. He hypothesized that students were transmitting "cadaverous particles" from the autopsy room to the delivery ward on their hands. When Semmelweis instituted a mandatory handwashing protocol using chlorinated lime solution, the mortality rate in the students'' ward dropped to levels comparable to the midwives'' ward within three months.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KXD33E', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the research vessel Polaris arrived at the Mariana Trench sampling site in March 2023, the crew discovered that hydrothermal vents in the area _______ microbial colonies unlike any previously cataloged in deep-sea biology.', $lyceon_json$[{"key":"A","text":"have sustained"},{"key":"B","text":"sustains"},{"key":"C","text":"had been sustaining"},{"key":"D","text":"will sustain"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence establishes a past-tense narrative ("arrived," "discovered") and reports what the crew found via a "that" clause. Because the vents'' sustaining of microbial colonies was an ongoing action already in progress before and at the time of the discovery, the past perfect progressive "had been sustaining" is correct. The present perfect "have sustained" violates the backshifting required after the past-tense reporting verb "discovered." The present-tense singular "sustains" fails on two counts: it does not agree with the plural subject "vents," and it breaks the past-tense narrative frame. The future tense "will sustain" illogically places the vents'' activity after the already-completed discovery.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M1DS2A', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Priya _______ has spent fourteen years studying firefly communication patterns in the Western Ghats, recently identified a species that emits a distinctive blue-green bioluminescent signal unknown to previous surveys of the region.', $lyceon_json$[{"key":"A","text":"Venkatesh, who"},{"key":"B","text":"Venkatesh; who"},{"key":"C","text":"Venkatesh. Who"},{"key":"D","text":"Venkatesh who"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause "who has spent fourteen years studying firefly communication patterns in the Western Ghats" is a nonrestrictive relative clause providing supplementary information about Priya Venkatesh, who is already identified by her full proper name. Nonrestrictive clauses must be set off by commas, making "Venkatesh, who" the correct choice. The semicolon option creates a sentence fragment after the semicolon because "who has spent..." is not an independent clause. The period option similarly creates a fragment beginning with "Who." The version without any punctuation incorrectly treats the clause as restrictive, implying there are multiple people named Priya Venkatesh who need to be distinguished—an illogical reading given the full proper name.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NSZQTQ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'A 2023 study by agricultural economists at the University of Wageningen found that vertical farms in the Netherlands use 93 percent less water per kilogram of produce than conventional field agriculture. _______ the study noted that vertical farms consume roughly 38 kilowatt-hours of electricity per kilogram of leafy greens, compared to just 1.7 kilowatt-hours for field-grown equivalents, raising concerns about the overall environmental footprint of indoor farming.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"However,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Therefore,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence presents a positive finding about vertical farms (93 percent less water use), while the sentence after the blank presents a negative finding (much higher electricity consumption and environmental concerns). This contrast requires a transition signaling an opposing point, making "However," the correct choice. "Furthermore," incorrectly signals additional supporting information, but the electricity data undermines rather than reinforces the water-savings advantage. "Specifically," wrongly suggests the second sentence elaborates on water savings, when it actually shifts to an entirely different metric (electricity). "Therefore," incorrectly implies the environmental concern is a logical conclusion of the water savings, when it is actually a counterpoint derived from a separate finding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ORO8MT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Cognitive scientist Priya Venkataraman has proposed that bilingual individuals do not simply switch between two discrete language systems but instead draw on a single integrated lexicon in which both languages coexist. Her 2022 fMRI study showed overlapping neural activation patterns in bilinguals processing Kannada and English words with shared etymological roots. _______ when bilinguals in the same study encountered words with no cross-linguistic cognates, the activation patterns diverged sharply, suggesting that the degree of lexical integration varies depending on the historical relationship between specific word pairs.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"In addition,"},{"key":"C","text":"By contrast,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'C', NULL, E'The preceding sentence describes overlapping neural activation for words with shared etymological roots, while the sentence after the blank describes sharply divergent activation for words without such roots. This directly contrasting experimental condition and outcome requires "By contrast," which correctly signals that the new finding opposes the pattern described in the previous sentence. "Similarly," incorrectly signals a parallel finding, but divergent activation patterns are the opposite of the overlapping patterns just described. "In addition," suggests merely adding more supporting evidence, failing to capture the oppositional relationship between the two experimental conditions (cognates versus non-cognates). "For instance," incorrectly frames the divergent-activation finding as an example of the overlapping-activation finding, when it is actually a contrasting result from a different experimental condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OY6752', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'The geologist Tanya Atwater spent decades mapping the tectonic history of western North America. Her reconstructions of ancient plate boundaries required synthesizing evidence from magnetic anomalies, sedimentary records, and fault geometries — data sets that, taken individually, offered only ______ glimpses of the region''s deep past but, combined, revealed a coherent narrative of continental transformation.', $lyceon_json$[{"key":"A","text":"fragmentary"},{"key":"B","text":"redundant"},{"key":"C","text":"simultaneous"},{"key":"D","text":"illicit"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts data sets that individually provide incomplete views with their combined power to reveal a coherent narrative. "Fragmentary" means consisting of small, incomplete parts, which precisely captures the idea that each data set alone offered only partial insight. "Redundant" means unnecessarily repetitive, which contradicts the passage''s point that each data set contributed distinct evidence. "Simultaneous" means occurring at the same time, which describes timing rather than completeness and does not logically contrast with the combined coherent narrative. "Illicit" means forbidden or unlawful, which is entirely unrelated to the scientific context described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P3VVMC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the Stavanger Oceanic Institute hypothesize that the sharp decline in Norwegian lobster (Nephrops norvegicus) populations in the Skagerrak strait since 2017 is primarily caused by increased sedimentation from coastal construction projects, which smothers the muddy burrows the lobsters depend on for shelter. The researchers note that lobster populations in adjacent areas without recent construction activity have remained stable over the same period.', $lyceon_json$[{"key":"A","text":"Sediment levels in Skagerrak burrow sites have increased by 45 percent since construction began, and lobsters experimentally exposed to equivalent sediment loads abandon their burrows within 72 hours."},{"key":"B","text":"Norwegian lobsters in aquarium settings prefer rocky substrates over muddy ones when both are available."},{"key":"C","text":"Water temperature in the Skagerrak has risen by 1.3 degrees Celsius since 2017, which may affect lobster metabolism."},{"key":"D","text":"Coastal construction projects in the Skagerrak use environmentally certified materials that minimize chemical pollution."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesize that sedimentation from construction smothers burrows, causing population decline. The finding about sediment increases of 45 percent and lobsters abandoning burrows under equivalent loads directly supports both the mechanism (sedimentation smothers burrows) and the consequence (lobsters lose shelter). The finding about aquarium substrate preference is irrelevant to the sedimentation-and-burrow-smothering mechanism in wild populations. The finding about rising water temperature introduces an alternative explanation that competes with rather than supports the researchers'' hypothesis. The finding about environmentally certified materials actually weakens the hypothesis by suggesting construction might not be causing harmful sediment effects.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RT7MG9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In a 2019 study of microbial communities in deep-sea hydrothermal vents, researchers found that certain archaea had developed metabolic pathways with no known analogs in surface organisms. The biochemist Maren Jørgensen cautioned against interpreting this finding as evidence that vent ecosystems operate independently of the broader ocean biosphere, arguing instead that the apparent ______ of these pathways likely reflects gaps in our sampling of intermediate environments rather than genuine biochemical isolation.', $lyceon_json$[{"key":"A","text":"singularity"},{"key":"B","text":"uniformity"},{"key":"C","text":"profitability"},{"key":"D","text":"durability"}]$lyceon_json$::jsonb, 'A', NULL, E'Jørgensen argues that metabolic pathways appearing to have no analogs elsewhere seem unique, but this apparent uniqueness stems from incomplete sampling rather than true isolation. "Singularity" means the quality of being one of a kind, which precisely captures the perceived uniqueness that Jørgensen attributes to sampling gaps. "Uniformity" means sameness or consistency, which is the opposite of what the passage describes — the pathways are notable precisely because they lack known analogs. "Profitability" refers to financial gain, which is irrelevant to the biochemical context. "Durability" means the ability to withstand wear or time, which does not address the question of whether these pathways are unique to vent ecosystems.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U63F5D', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare orchid specimens that the botanical garden acquired from a private estate last spring _______ now housed in a climate-controlled greenhouse designed to replicate tropical humidity levels.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," a singular noun, so the verb must be singular. "Is" correctly agrees with "collection" in both number and tense, fitting the present-tense indicator "now." The plural "are" incorrectly agrees with the nearer noun "specimens," which is the object of a prepositional phrase, not the subject. "Were" is both plural and past tense, conflicting with the singular subject and the present-tense context established by "now." "Have been" is plural, failing to agree with the singular "collection."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UFZXCP', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central idea of the text?', E'Intuition has an uneven record in physics. Consider the long-debated Mpemba effect -- the counterintuitive observation, first documented by Tanzanian student Erasto Mpemba in 1963, that hot water can freeze faster than cold water under certain conditions. For decades, physicists dismissed, confirmed, and re-dismissed the phenomenon, with Xi Zhang''s 2014 simulations attributing it to hydrogen-bond memory in heated water molecules. Yet a 2020 replication study by Burridge and Linden at Cambridge found that when container geometry, evaporation rate, and dissolved-gas content were rigorously controlled, the effect vanished in 27 of 29 trials. The two remaining positive results fell within measurement uncertainty. This trajectory -- from startling anecdote to contested evidence to likely artifact of uncontrolled variables -- mirrors a broader pattern in which initially surprising empirical claims survive peer review only until experimental controls catch up with the phenomenon''s complexity.', $lyceon_json$[{"key":"A","text":"It serves as a case study illustrating how initially counterintuitive empirical claims can dissolve under increasingly rigorous experimental controls."},{"key":"B","text":"It provides definitive proof that intuition is always unreliable in scientific research and should be replaced by computational modeling."},{"key":"C","text":"It demonstrates that Erasto Mpemba's original 1963 findings were fundamentally flawed due to his lack of formal physics training."},{"key":"D","text":"It highlights the superiority of Zhang's 2014 hydrogen-bond memory theory over the Cambridge group's replication methodology."}]$lyceon_json$::jsonb, 'A', NULL, E'The text traces the history of the Mpemba effect from its initial observation through contested evidence to its likely status as an artifact of uncontrolled variables, then explicitly states that this trajectory mirrors a broader pattern in which surprising empirical claims survive only until experimental controls catch up. The choice stating that counterintuitive empirical claims can dissolve under increasingly rigorous experimental controls captures this central idea. The choice claiming that intuition is always unreliable and should be replaced by computational modeling overstates the text, which describes an uneven record rather than a universal rule, and the text does not advocate for replacing intuition with modeling. The choice about Mpemba''s lack of formal training is unsupported: the text attributes the effect''s dissolution to better controls, not to Mpemba''s credentials. The choice about Zhang''s theory being superior to the Cambridge findings contradicts the text, which presents the Cambridge study as undermining earlier positive results including Zhang''s simulations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W6NWB8', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WY0DD3', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the relationship between Haloarchaea pigmentation and UV radiation exposure?', E'Haloarchaea -- salt-loving microorganisms found in hypersaline environments like the Dead Sea and Utah''s Great Salt Lake -- produce bacterioruberin, a C50 carotenoid pigment that gives salt flats their characteristic pinkish-red hue. Virologist Jocelyne DiRuggiero and her team at Johns Hopkins sampled Haloarchaea colonies from 13 hypersaline sites at latitudes ranging from 3 degrees to 67 degrees north. They found that colonies at higher latitudes -- which receive lower annual UV-B radiation -- produced bacterioruberin concentrations averaging 0.38 micrograms per milligram of dry cell mass, while equatorial colonies exposed to UV-B intensities roughly 2.7 times greater produced concentrations averaging 1.14 micrograms per milligram. When equatorial-latitude colonies were cultivated in laboratory conditions under UV-B levels matching those at 55 degrees north, their bacterioruberin output declined by 61 percent within nine generations, approaching the concentrations typical of naturally high-latitude populations.', $lyceon_json$[{"key":"A","text":"Bacterioruberin production in Haloarchaea is a fixed genetic trait that does not vary in response to environmental UV-B levels."},{"key":"B","text":"Haloarchaea at high latitudes have permanently lost the genetic capacity to produce elevated bacterioruberin concentrations."},{"key":"C","text":"Bacterioruberin production in Haloarchaea is responsive to ambient UV-B radiation levels rather than being solely determined by the geographic origin of the colony."},{"key":"D","text":"The pinkish-red color of hypersaline environments is caused primarily by mineral deposits rather than by microbial pigmentation."}]$lyceon_json$::jsonb, 'C', NULL, E'The laboratory experiment showed that equatorial colonies reduced their bacterioruberin output by 61 percent when grown under lower UV-B levels, approaching high-latitude concentrations. This demonstrates that production responds to ambient UV-B rather than being fixed by geographic origin. The option calling it a fixed genetic trait directly contradicts the experimental finding that output changed when UV conditions changed. The option about permanently lost genetic capacity is too strong -- the experiment showed equatorial colonies can modulate production downward, but the passage does not test whether high-latitude colonies can increase production upward; regardless, the equatorial result alone disproves permanent genetic fixation. The option about mineral deposits contradicts the passage''s opening statement attributing the pinkish-red hue to bacterioruberin pigment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XCB56H', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about Varvara Stepanova''s approach to textile design?', E'In 1924, the Soviet constructivist artist Varvara Stepanova began designing fabrics for the First State Textile Print Factory in Moscow. Unlike her contemporaries who adapted floral and pastoral motifs from pre-revolutionary Russian design traditions, Stepanova created patterns using exclusively geometric forms -- circles, triangles, and intersecting linear grids -- arranged in dynamic, asymmetrical compositions. She argued that textile design should reflect the rhythm of industrial production rather than nostalgia for agrarian life. Her designs were intended for mass manufacture, and she deliberately constrained her color palettes to two or three hues per pattern to reduce production costs and ensure consistency across large print runs.', $lyceon_json$[{"key":"A","text":"She prioritized aesthetic novelty for gallery exhibition over practical considerations of mass production."},{"key":"B","text":"She believed that the visual language of modern industry was more appropriate for Soviet textiles than references to pre-revolutionary rural imagery."},{"key":"C","text":"She used complex, multi-layered color schemes to distinguish her work from the simpler designs of her contemporaries."},{"key":"D","text":"She regarded textile design as a lesser art form that did not warrant the creative investment she gave to painting and sculpture."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that Stepanova used geometric, industrial-rhythm-inspired forms instead of the floral and pastoral motifs her contemporaries adapted from pre-revolutionary traditions, and that she designed for mass manufacture. The inference that she believed industrial visual language was more appropriate than rural imagery for Soviet textiles follows directly. The option about prioritizing gallery exhibition contradicts the passage''s emphasis on mass manufacture, cost reduction, and production consistency. The option about complex multi-layered color schemes directly contradicts the stated two-or-three-hue constraint. The option about regarding textile design as a lesser art form is unsupported -- the passage describes her deliberate, theoretically motivated engagement with the medium.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y140ZE', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research report about urban heat islands. The student wants to present a contrast between two cities'' approaches to mitigating extreme heat. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
